"use client";

import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function HistorySentTime({ value }: { value: string | null }) {
  const hydrated = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );

  if (!value) return <span>—</span>;

  const date = new Date(value);
  return (
    <time
      className="history-sent-time grid gap-0.5 text-[13.5px]"
      dateTime={value}
    >
      <span>
        {hydrated
          ? new Intl.DateTimeFormat(undefined, { dateStyle: "medium" }).format(
              date,
            )
          : value.slice(0, 10)}
      </span>
      <span className="text-[var(--h-muted)] text-[13px]">
        {hydrated
          ? new Intl.DateTimeFormat(undefined, { timeStyle: "short" }).format(
              date,
            )
          : `${value.slice(11, 16)} UTC`}
      </span>
    </time>
  );
}
